    # Full-width/height uniform lines mark the repeated-cell separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_cuts = [-1] + sep_rows + [h]
    col_cuts = [-1] + sep_cols + [w]
    row_tiles = [(row_cuts[i] + 1, row_cuts[i + 1]) for i in range(len(row_cuts) - 1)]
    col_tiles = [(col_cuts[i] + 1, col_cuts[i + 1]) for i in range(len(col_cuts) - 1)]
    # Ignore empty tiles; choose the tile with the greatest number of non-background cells.
    candidates = []
    for ri, (r0, r1) in enumerate(row_tiles):
        for ci, (c0, c1) in enumerate(col_tiles):
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            if vals:
                counts = {}
                for v in vals:
                    counts[v] = counts.get(v, 0) + 1
                bg = max(counts, key=counts.get)
                score = sum(v != bg for v in vals)
                candidates.append((score, ri, ci, r0, r1, c0, c1))
    _, sri, sci, sr0, sr1, sc0, sc1 = max(candidates)
    pattern = [grid[r][sc0:sc1] for r in range(sr0, sr1)]
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_tiles):
        for ci, (c0, c1) in enumerate(col_tiles):
            if ri == sri and ci == sci:
                continue
            for dr, r in enumerate(range(r0, r1)):
                for dc, c in enumerate(range(c0, c1)):
                    out[r][c] = pattern[dr % len(pattern)][dc % len(pattern[0])]
    return out
