 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    row_separators = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    col_separators = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    row_bounds = [-1] + row_separators + [h]
    col_bounds = [-1] + col_separators + [w]
    row_tiles = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_tiles = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    # Select the tile containing the most non-background pattern cells.
    best = None
    for ri, (r0, r1) in enumerate(row_tiles):
        for ci, (c0, c1) in enumerate(col_tiles):
            if r0 == r1 or c0 == c1:
                continue
            score = sum(grid[r][c] != background for r in range(r0, r1) for c in range(c0, c1))
            if best is None or score > best[0]:
                best = (score, ri, ci, r0, r1, c0, c1)
    _, source_ri, source_ci, sr0, sr1, sc0, sc1 = best
    pattern = [grid[r][sc0:sc1] for r in range(sr0, sr1)]
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_tiles):
        for ci, (c0, c1) in enumerate(col_tiles):
            if ri == source_ri and ci == source_ci:
                continue
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = pattern[(r - r0) % len(pattern)][(c - c0) % len(pattern[0])]
    return out
